// --- PBR environment pass: procedural high-frequency surface maps ---
function makeSurfaceMap(kind,repeatX=4,repeatY=4){
 const c=document.createElement("canvas");c.width=c.height=512;const ctx=c.getContext("2d"),img=ctx.createImageData(512,512);
 let seed=kind.split("").reduce((a,v)=>a+v.charCodeAt(0),17);const rnd=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
 const palettes={grass:[70,112,54],sand:[184,155,105],wood:[105,70,43],roof:[112,54,43],stone:[112,119,112],path:[163,143,104],leaf:[63,112,60]};
 const p=palettes[kind]||palettes.grass;
 for(let i=0;i<img.data.length;i+=4){const n=(rnd()-.5)*34;img.data[i]=Math.max(0,Math.min(255,p[0]+n));img.data[i+1]=Math.max(0,Math.min(255,p[1]+n));img.data[i+2]=Math.max(0,Math.min(255,p[2]+n));img.data[i+3]=255}
 ctx.putImageData(img,0,0);
 if(kind==="wood"||kind==="roof"||kind==="path"){for(let i=0;i<90;i++){ctx.strokeStyle="rgba(30,20,12,"+(rnd()*.16)+")";ctx.lineWidth=.5+rnd()*2;ctx.beginPath();let y=rnd()*512;ctx.moveTo(0,y);ctx.bezierCurveTo(150,y+(rnd()-.5)*16,350,y+(rnd()-.5)*20,512,y+(rnd()-.5)*12);ctx.stroke()}}
 if(kind==="grass"||kind==="leaf"){for(let i=0;i<1300;i++){ctx.fillStyle=rnd()>.5?"rgba(190,220,135,.16)":"rgba(20,55,22,.14)";ctx.beginPath();ctx.ellipse(rnd()*512,rnd()*512,1+rnd()*3,.5+rnd()*2,rnd()*3,0,Math.PI*2);ctx.fill()}}
 const tex=new THREE.CanvasTexture(c);tex.colorSpace=THREE.SRGBColorSpace;tex.wrapS=tex.wrapT=THREE.RepeatWrapping;tex.repeat.set(repeatX,repeatY);tex.anisotropy=Math.min(8,renderer?.capabilities?.getMaxAnisotropy?.()||4);return tex;
}
function makeWaterNormalMap(){const c=document.createElement("canvas");c.width=c.height=256;const ctx=c.getContext("2d"),img=ctx.createImageData(256,256);for(let y=0;y<256;y++)for(let x=0;x<256;x++){const i=(y*256+x)*4,nx=Math.sin(x*.095+Math.sin(y*.035)*1.8)*.18,ny=Math.cos(y*.085+Math.sin(x*.04)*1.5)*.16,nz=Math.sqrt(Math.max(.7,1-nx*nx-ny*ny));img.data[i]=Math.round((nx*.5+.5)*255);img.data[i+1]=Math.round((ny*.5+.5)*255);img.data[i+2]=Math.round((nz*.5+.5)*255);img.data[i+3]=255}ctx.putImageData(img,0,0);const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.NoColorSpace;t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(4,4);return t}
function applyPbrMaterials(){
 const sets=[["grass",mat.grass,8,8,.12],["grass",mat.grass2,7,7,.10],["sand",mat.sand,5,5,.06],["wood",mat.wood,2,3,.11],["roof",mat.roof,3,3,.08],["stone",mat.stone,3,3,.14],["path",mat.path,4,4,.05],["leaf",mat.leaf,3,3,.08]];
 sets.forEach(([kind,m,rx,ry,bump])=>{const map=makeSurfaceMap(kind,rx,ry),bumpMap=map.clone();bumpMap.colorSpace=THREE.NoColorSpace;m.map=map;m.bumpMap=bumpMap;m.bumpScale=bump;m.roughness=kind==="stone"?.92:.86;m.needsUpdate=true});
}
function addGrassField(){
 const positions=[-.035,0,0,.035,0,0,0,.43,0,0,0,-.035,0,0,.035,0,.43,0];
 const geo=new THREE.BufferGeometry();geo.setAttribute("position",new THREE.Float32BufferAttribute(positions,3));geo.setIndex([0,1,2,3,4,5]);geo.computeVertexNormals();
 const material=new THREE.MeshStandardMaterial({color:0xffffff,roughness:1,side:THREE.DoubleSide});
 const count=quality.grassCount,mesh=new THREE.InstancedMesh(geo,material,count),dummy=new THREE.Object3D(),col=new THREE.Color();let placed=0,tries=0;
 while(placed<count&&tries<count*5){tries++;const x=(Math.random()-.5)*88,z=(Math.random()-.5)*88,r=Math.hypot(x,z);if(r<10||r>44)continue;
 if(Math.abs(x)<3&&z>-22&&z<23)continue;if(Math.abs(z+12)<2.4&&x>-12&&x<21)continue;if(Math.abs(x+15)<1.8&&z>-12&&z<12)continue;if(Math.abs(x-16)<1.8&&z>-12&&z<12)continue;
 const y=terrainHeight(x,z);dummy.position.set(x,y,z);dummy.rotation.set(0,Math.random()*Math.PI,0);const sc=.55+Math.random()*1.15;dummy.scale.set(sc,sc,sc);dummy.updateMatrix();mesh.setMatrixAt(placed,dummy.matrix);const tint=.78+Math.random()*.38;col.setRGB(.63*tint,.92*tint,.56*tint);mesh.setColorAt(placed,col);placed++}
 mesh.count=placed;mesh.instanceMatrix.needsUpdate=true;if(mesh.instanceColor)mesh.instanceColor.needsUpdate=true;mesh.frustumCulled=false;scene.add(mesh);
}
function addRoofDetail(g,side,roofMat){
 for(let row=0;row<6;row++)for(let col=0;col<5;col++){const x=side*(.22+col*.39),z=-1.62+row*.64,y=2.9+(.78-Math.abs(x))*.72+.10;const tile=box(g,x,y,z,.39,.085,.62,roofMat);tile.rotation.z=side<0?.62:-.62;tile.castShadow=true}
}

function terrainHeight(x,z){const r=Math.hypot(x,z);const hills=[[ -25,-24,1.15,8],[-34,-8,.72,7],[28,24,.85,9],[25,-25,.62,7],[-5,35,.5,8]];let h=.10*Math.sin(x*.17)*Math.cos(z*.13)+.07*Math.sin((x+z)*.31);for(const [hx,hz,amp,spread] of hills){const d=((x-hx)**2+(z-hz)**2)/(spread*spread);h+=amp*Math.exp(-d*1.6)}return h-Math.max(0,r-43)*.11;}
function makeTerrain(){const rings=112,segments=256,positions=[],colors=[],indices=[];const c=new THREE.Color();for(let i=0;i<=rings;i++){const t=i/rings,r=t*49;for(let j=0;j<=segments;j++){const a=j/segments*Math.PI*2,x=Math.cos(a)*r,z=Math.sin(a)*r,y=terrainHeight(x,z);positions.push(x,y,z);let shade=.94+.045*Math.sin(x*.31+z*.19)+.025*Math.cos(z*.43);c.setRGB(.40*shade,.66*shade,.36*shade);if(r>43)c.lerp(new THREE.Color(0xb8a46e),Math.min(1,(r-43)/6)*.8);colors.push(c.r,c.g,c.b);if(i<rings&&j<segments){const n=i*(segments+1)+j;indices.push(n,n+1,n+segments+1,n+1,n+segments+2,n+segments+1)}}}const g=new THREE.BufferGeometry();g.setAttribute("position",new THREE.Float32BufferAttribute(positions,3));g.setAttribute("color",new THREE.Float32BufferAttribute(colors,3));g.setIndex(indices);g.computeVertexNormals();const mesh=new THREE.Mesh(g,new THREE.MeshStandardMaterial({vertexColors:true,map:makeSurfaceMap("grass",9,9),roughness:.96,bumpMap:makeSurfaceMap("grass",9,9),bumpScale:.08}));mesh.receiveShadow=true;mesh.castShadow=false;return mesh;}
function addSky(){const sky=new THREE.Mesh(new THREE.SphereGeometry(230,48,32),new THREE.ShaderMaterial({side:THREE.BackSide,depthWrite:false,vertexShader:"varying vec3 vWorld; void main(){vec4 p=modelMatrix*vec4(position,1.0);vWorld=p.xyz;gl_Position=projectionMatrix*viewMatrix*p;}",fragmentShader:"varying vec3 vWorld; void main(){float h=normalize(vWorld).y;vec3 top=vec3(0.20,0.48,0.68);vec3 mid=vec3(0.64,0.83,0.91);vec3 low=vec3(0.91,0.88,0.76);vec3 col=mix(low,mid,smoothstep(-0.12,0.34,h));col=mix(col,top,smoothstep(0.28,0.92,h));gl_FragColor=vec4(col,1.0);}" }));scene.add(sky);const sun=new THREE.Mesh(new THREE.SphereGeometry(3.4,32,24),new THREE.MeshBasicMaterial({color:0xfff1c8}));sun.position.set(-62,72,-95);scene.add(sun);const glow=new THREE.PointLight(0xffe4b4,1.4,150);glow.position.copy(sun.position);scene.add(glow);}
const C={grass:0x79b879,grass2:0x8bc77e,sand:0xe7cf91,water:0x4eabc0,wood:0x986543,cream:0xf5e7c8,roof:0xc97868,leaf:0x4f9562,stone:0x999d9a,blue:0x80c4d5};
const mat={grass:M(C.grass),grass2:M(C.grass2),sand:M(C.sand),water:M(C.water,.45),wood:M(C.wood),cream:M(C.cream),roof:M(C.roof),leaf:M(C.leaf),stone:M(C.stone),path:M(0xd9c18b),white:M(0xf6eedc),dark:M(0x59483e),gold:M(0xe9bf64),blue:M(C.blue)};
function read(){try{const saved=JSON.parse(localStorage.getItem(WORLD)||"{}");data={...data,...saved};for(const key of ["shells","fruit","crystals","placed","visited","questFlags"])if(!Array.isArray(data[key]))data[key]=[];data.friendship=data.friendship&&typeof data.friendship==="object"?data.friendship:{};adv=JSON.parse(localStorage.getItem(ADV)||"{}");adv.upgrades=adv.upgrades&&typeof adv.upgrades==="object"?adv.upgrades:{}}catch(e){console.warn("Inselspielstand konnte nicht vollständig gelesen werden.",e)}}
