function makeNpc(x,z,name,shirt,skin,lines,role){let g=group(scene,x,0,z),body=group(g);cyl(body,0,.82,0,.38,.43,.86,M(shirt));ball(body,0,1.53,0,.34,M(skin));ball(body,0,1.82,-.03,.36,M(0x684b39));ball(body,-.13,1.6,.3,.055,mat.dark);ball(body,.13,1.6,.3,.055,mat.dark);ball(body,0,1.43,.32,.045,M(0xc87870));for(let side of [-1,1]){let arm=box(body,side*.42,.93,0,.16,.62,.17,M(shirt));arm.rotation.z=side*.18;let hand=ball(body,side*.43,.61,.02,.12,M(skin));let leg=cyl(body,side*.15,.22,0,.13,.14,.42,M(0x665a52),9);leg.position.z=0}let hat=cone(body,0,2.02,0,.43,.3,M(0xe5c27b),8);hat.rotation.y=.2;const routes={guide:[[0,0],[-2,4],[3,3],[1,-3]],builder:[[10,-2],[8,4],[12,1],[7,-4]],gardener:[[-12,-8],[-9,-5],[-14,-3],[-10,-11]],forest:[[-31,-20],[-28,-18],[-34,-23]],beach:[[31,20],[34,17],[29,24],[27,18]]};const npc={g,x,z,phase:npcs.length*1.7,baseX:x,baseZ:z,body,role,lines,route:routes[role]||[[x,z]]};npcs.push(npc);const models={guide:"human013/FairyGodmother.glb",builder:"human016/ClanSmith.glb",gardener:"human017/SunflowerGrower.glb",forest:"human016/WolfQueen.glb",beach:"human016/MeadMaiden.glb"};loadRiggedCharacter(GOBKIT+(models[role]||"human017/FarmHand.glb"),g,2.0);const talk={x,z,r:2.8,title:name,kind:"npc",lines,role,npc};npc.interactable=talk;things.push(talk)}
function pickup(x,z,id,type){let g=group(scene,x,.18,z);if(type==="shell"){ball(g,0,0,0,.25,M(0xf4d6b0));g.scale.set(1,.55,.8)}else if(type==="fruit"){ball(g,0,0,0,.22,M(0xe85c55));cyl(g,0,.22,0,.025,.025,.18,mat.leaf,6)}else{let o=new THREE.Mesh(new THREE.OctahedronGeometry(.32),mat.blue);g.add(o);ball(g,0,0,0,.12,mat.gold)}pickups.push({g,x,z,id,type})}
