function loadIslandEnvironment(){
 // HDRI environment is loaded into the REAL playable island, not the isolated preview.
 // Poly Haven Kloppenheim 06 Pure Sky, CC0, 1K. PMREM keeps reflections efficient.
 const pmrem=new THREE.PMREMGenerator(renderer);
 pmrem.compileEquirectangularShader();
 new RGBELoader().setDataType(THREE.HalfFloatType).load(
  "https://dl.polyhaven.org/file/ph-assets/HDRIs/hdr/1k/kloppenheim_06_puresky_1k.hdr",
  hdr=>{
   try{
    const env=pmrem.fromEquirectangular(hdr).texture;
    scene.environment=env;
    scene.environmentIntensity=.72;
    hdr.dispose();
   }catch(error){console.warn("Insel-HDRI konnte nicht verarbeitet werden:",error);hdr.dispose();}
   pmrem.dispose();
  },
  undefined,
  error=>{console.warn("Insel-HDRI nicht erreichbar; Standardbeleuchtung bleibt aktiv.",error);pmrem.dispose();}
 );
}
function buildWorld(){
 applyPbrMaterials();
 scene.background=new THREE.Color(0x8fc5dc);scene.fog=new THREE.FogExp2(0x9fcbd5,.0034);addSky();
 dayHemi=new THREE.HemisphereLight(0xe7f4ff,0x53674a,1.45);scene.add(dayHemi);dayAmbient=new THREE.AmbientLight(0xffffff,.16);scene.add(dayAmbient);
 daySun=new THREE.DirectionalLight(0xffedcf,3.6);daySun.position.set(-30,55,24);daySun.castShadow=true;daySun.shadow.mapSize.set(quality.shadowSize,quality.shadowSize);daySun.shadow.bias=-.00018;daySun.shadow.normalBias=.025;daySun.shadow.camera.left=-62;daySun.shadow.camera.right=62;daySun.shadow.camera.top=62;daySun.shadow.camera.bottom=-62;daySun.shadow.camera.near=1;daySun.shadow.camera.far=150;daySun.shadow.radius=4;scene.add(daySun);
 waterNormalMap=makeWaterNormalMap();let seaMat=new THREE.MeshPhysicalMaterial({color:0x4b9fb6,metalness:.16,roughness:.22,clearcoat:1,clearcoatRoughness:.08,reflectivity:.8,normalMap:waterNormalMap,normalScale:new THREE.Vector2(.28,.28)});let sea=new THREE.Mesh(new THREE.CircleGeometry(180,256),seaMat);sea.rotation.x=-Math.PI/2;sea.position.y=-.8;sea.userData.basePositions=sea.geometry.attributes.position.array.slice();waterMesh=sea;scene.add(sea);
 let island=new THREE.Mesh(new THREE.CircleGeometry(54,192),M(0xd9bd83,.96));island.rotation.x=-Math.PI/2;island.position.y=-.24;scene.add(island);
 let land=makeTerrain();scene.add(land);addGrassField();let shore=new THREE.Mesh(new THREE.TorusGeometry(49,.62,12,256),M(0xe3d09c,.92));shore.rotation.x=Math.PI/2;shore.position.y=-.02;scene.add(shore);for(let i=0;i<180;i++){let a=i*2.399,r=15+(i%13)*2.45,x=Math.cos(a)*r,z=Math.sin(a)*r;let tuft=cone(scene,x,terrainHeight(x,z)+.19,z,.08,.27,M(i%2?0x6da96d:0x94c77b),6);tuft.rotation.z=(i%3-1)*.2;}
 // four distinct districts and central village
 path(0,4,5,38);path(0,-12,34,3.5);path(-15,1,3,29);path(16,-1,3,29);path(0,19,28,3);
 let plaza=new THREE.Mesh(new THREE.CircleGeometry(8,48),M(0xd7c18e));plaza.rotation.x=-Math.PI/2;plaza.position.set(0,.09,1);scene.add(plaza);
 house(-7,1,0xf1d8ae,0xc97d67,"Miras Haus","home");house(8,1,0xd6e7c8,0x8c9bc7,"Noahs Werkstatt","workshop");house(-7,-12,0xf1d0b7,0x6e9e91,"Dein Inselhaus","home");house(16,-14,0xe6d8f0,0x9b83b7,"Die Sternenbibliothek","library");
 // village trees and flower beds
 for(let i=0;i<22;i++){let a=i*2.4,r=25+(i%4)*3;tree(Math.cos(a)*r,Math.sin(a)*r,.8+(i%3)*.12,i%4===0?2:0)}
 for(let i=0;i<70;i++){let x=-13+(i%14)*.85,z=-5+Math.floor(i/14)*.8;flower(x,z,[0xf4a8c7,0xffdf83,0xc6b0ff,0xffffff][i%4])}
 // whisper forest in north
 for(let i=0;i<30;i++){let x=-34+(i%6)*3,z=-31+Math.floor(i/6)*4;tree(x,z,1.1+(i%3)*.15,1)}
 // garden east
 for(let i=0;i<24;i++){let x=22+(i%6)*2.3,z=-3+Math.floor(i/6)*2.1;flower(x,z,[0xffb1d2,0xffe28c,0xb8a5ff][i%3])}
 // beach and lighthouse south
 for(let i=0;i<10;i++){let a=i*.62;tree(Math.cos(a)*43,Math.sin(a)*43,.65,1)}
 let light=group(scene,36,0,27);light.userData.lighthousePlaceholder=true;cyl(light,0,2.8,0,1.1,1.4,5.6,mat.white,16);cyl(light,0,5.8,0,.9,.9,.35,mat.wood,16);cyl(light,0,6.35,0,.6,.6,.8,mat.gold,12);cone(light,0,7,0,.8,.8,mat.roof,8);collider(36,27,1.5);things.push({x:36,z:27,r:4,title:"Alter Leuchtturm",kind:"sign",lines:["Von hier aus sieht man die ganze Sterneninsel.","Die Laterne leuchtet heller, wenn du neue Dinge lernst."]});
 // rocks, ponds, bridges, picnic spots
 let pond=new THREE.Mesh(new THREE.CircleGeometry(5,64),new THREE.MeshPhysicalMaterial({color:0x4faeb8,roughness:.16,metalness:.12,clearcoat:1,clearcoatRoughness:.04}));pond.rotation.x=-Math.PI/2;pond.position.set(27,.10,13);scene.add(pond);let pondRim=new THREE.Mesh(new THREE.TorusGeometry(5,.18,10,64),M(0xaaa58b));pondRim.rotation.x=Math.PI/2;pondRim.position.set(27,.16,13);scene.add(pondRim);
 for(let i=0;i<9;i++){let rock=ball(scene,-27+(i%3)*2,.35,-16+Math.floor(i/3)*2,.8,M(0x929d9b));rock.scale.set(1,.7,1.2)}
 for(let [x,z] of [[-18,12],[18,17],[0,-27],[31,-20],[-31,27]]){bench(x,z);lamp(x+1,z)}
 makeNpc(-2,0,"Mira",0x719cdb,0xf0c5a2,["Du musst der Brief deiner Großmutter sein. Ich bin Mira. Nach dem Sturm ist es still geworden, aber vielleicht beginnt heute etwas Neues.","Noah hat noch die alten Pläne des Dorfplatzes. Wenn ihr ihn wieder schön macht, kommen die Nachbarn vielleicht zurück.","Der Blütengarten war einmal der Lieblingsort vieler Familien. Lio kennt die alten Samen und braucht bestimmt Hilfe.","Tavi bewacht den Flüsterwald. Die Kristalle dort könnten zu unserer alten Sternenkarte gehören.","Neri wartet an der Bucht. Sie kennt die Geschichte der Schiffe und des Leuchtturms besser als alle anderen.","Die Kristalle passen zu den alten Zeichen am Leuchtturm. Noah kann die Mechanik reparieren – wir müssen es gemeinsam versuchen.","Der Leuchtturm leuchtet wieder. Lass uns ein Lichterfest feiern und alle willkommen heißen, die zurückkehren möchten."],"guide");
 makeNpc(10,-2,"Noah",0xd68d72,0xc68c66,["Ich bin Noah. Meine Werkstatt hat den Sturm überstanden, aber der Dorfplatz braucht dringend etwas Pflege. Mit B öffnest du den Baumodus.","Die alten Pläne sind noch brauchbar. Stell erst einmal zwei Dinge auf – eine Bank oder Laterne macht den Platz gleich freundlicher.","Lio hat mich nach neuen Beeten gefragt. Im Garten könnten wir aus den alten Samen etwas Besonderes machen.","Tavi hat einen Sternenkristall gefunden. Sie glaubt, dass mehrere davon zusammen eine Karte ergeben.","Neri möchte den Hafen wieder öffnen. Ohne ein zuverlässiges Licht am Leuchtturm ist das aber zu gefährlich.","Ich habe die Mechanik geprüft. Mit den Kristallen und etwas Geld können wir das Leuchtfeuer wieder in Gang setzen.","Die Lampe funktioniert! Ich kümmere mich um die Lichter für das Fest. Diesmal soll der ganze Platz strahlen."],"builder");
 makeNpc(-12,-8,"Lio",0x8ebd7d,0xf1c6a0,["Ich bin Lio. Ich kümmere mich um die Pflanzen am Dorfrand. Vielleicht können wir den alten Garten bald wieder öffnen.","Ein paar Blumen sind schon zurückgekommen. Der Platz braucht noch etwas Pflege und neue Dekoration.","Hier sind die Samen meiner Familie. Sammle ein paar Früchte und hilf mir, die Beete wiederzubeleben.","Wenn du in den Wald gehst, halte nach den Sternenkristallen Ausschau. Früher haben sie die Wege markiert.","Die Blumen am Strand erinnern mich an die alten Sommerfeste. Vielleicht sehen wir dort bald wieder mehr Boote.","Ich habe ein paar Pflanzen für den Leuchtturm zusammengestellt. Ein heller Ort soll auch freundlich aussehen.","Für das Lichterfest bringe ich Blumen auf den Dorfplatz. Es soll sich anfühlen wie früher – nur mit neuen Erinnerungen."],"gardener");
 makeNpc(-31,-20,"Tavi",0x9d83c7,0xf0c6a0,["Ich bin Tavi. Der Flüsterwald bewahrt viele Geschichten. Der Weg ist noch verschlossen, aber du wirst ihn zur richtigen Zeit entdecken.","Die Bäume stehen wieder dichter. Ich habe Spuren gefunden, die tiefer in den Wald führen.","Die ersten Kristalle sind nur ein Teil der Sternenkarte. Suche weiter und bringe Licht in die alten Geschichten.","Diese Kristalle gehören zu einer Karte, die bis zur Küste reicht. Neri kann dir sagen, was dort wartet.","Der Pfad zum Meer ist wieder offen. Die Sternenbucht könnte der Schlüssel zur alten Seeroute sein.","Die Karte zeigt den Leuchtturm. Wenn sein Licht zurückkehrt, finden die Schiffe wieder zur Insel.","Ich werde beim Fest die Geschichte der Sternenkarte erzählen. Manche Geheimnisse werden schöner, wenn man sie teilt."],"forest");
 makeNpc(31,20,"Neri",0xd58fbb,0xf1c6a0,["Ich bin Neri. Von hier aus kann man weit aufs Meer sehen. Früher kamen täglich Schiffe in unsere Bucht.","Die Muscheln am Strand stammen manchmal von weit her. Vielleicht findest du genug, um unsere Sammlung zu ergänzen.","Wenn der Wald wieder zugänglich ist, kann Tavi dir mehr über die Kristalle erzählen.","Die Sternenkarte führt wirklich bis zum Meer. Ich erkenne die alte Route – doch ohne Leuchtturmlicht ist sie kaum zu finden.","Du hast die Bucht wiederentdeckt. Sammle Muscheln und hilf mir, die alte Route vorzubereiten.","Mit einem restaurierten Leuchtturm können wir die Schiffe wieder sicher lotsen. Ich werde die erste Reise organisieren.","Das erste Schiff ist zurück! Zum Lichterfest bringe ich Geschichten aus der Ferne mit."],"beach");
 for(let i=0;i<16;i++){let a=i*2.4;pickup(Math.cos(a)*39,Math.sin(a)*39,"shell"+i,"shell")}
 for(let i=0;i<12;i++)pickup(20+(i%4)*3,-8+Math.floor(i/4)*3,"fruit"+i,"fruit");
 for(let i=0;i<8;i++)pickup(-29+(i%4)*3,-26+Math.floor(i/4)*3,"crystal"+i,"crystal");
 sign(0,10,"Insel-Kompass",["Die Wege führen zu Dorf, Garten, Wald und Strand.","Nutze WASD oder die Pfeiltasten. E öffnet Gespräche und sammelt Dinge."]);sign(5,8,"Das Schwarze Brett",["Heute auf der Sterneninsel: Schau bei deinen Nachbarn vorbei und entdecke, was sich verändert hat.","Die Bewohner haben eigene Wege und treffen sich nicht immer am selben Ort. Gespräche lassen eure Freundschaft wachsen."]);
 addPlacedObjects();if(adv.upgrades?.festival){lamp(-6,6);lamp(6,6);lamp(-6,-3);lamp(6,-3)}addSceneryDetails();loadFreeEnvironment();loadCloudModels();
}
function addSceneryDetails(){
 const pebble=M(0xa6aaa0),darkRock=M(0x747f7c),shrubA=M(0x477f55),shrubB=M(0x6da56a),mushroom=M(0xf0e3ca),cap=M(0xc96e62);
 // Uneven grassy knolls make the island silhouette feel less like a flat disc.
 for(let i=0;i<15;i++){let a=i*2.399,r=35+(i%4)*2.1,g=group(scene,Math.cos(a)*r,0,Math.sin(a)*r);let mound=ball(g,0,.18,0,1.8+(i%3)*.35,mat.grass2);mound.scale.set(1.35,.32,1.05);mound.rotation.y=a;}
 // Bushes are supplied by reusable authored GLB assets in loadFreeEnvironment().
 // Rock outcrops and cliff faces are supplied by authored GLB assets in loadFreeEnvironment().
 // Flowering bushes and tiny ground flowers add a more layered garden.
 for(let i=0;i<36;i++){let a=i*2.4,r=20+(i%4)*1.5,x=Math.cos(a)*r,z=Math.sin(a)*r;for(let j=0;j<3;j++){let g=group(scene,x+(j-1)*.32,.02,z+((j%2)-.5)*.35);ball(g,0,.25,0,.3,j%2?shrubB:shrubA);if(i%2===0)ball(g,0,.52,0,.13,M([0xf3a8c8,0xffd978,0xc6b0ff][(i+j)%3]))}}
 // Wooden fences frame the village garden and make spaces feel designed.
 for(let side=-1;side<=1;side+=2){for(let k=0;k<7;k++){let x=side*13,z=-5+k*1.5;cyl(scene,x,.42,z,.07,.07,.84,mat.wood,7);if(k<6)box(scene,x+side*.0,.58,z+.75,.1,.1,1.5,mat.cream)}}
 // Reeds and lily pads around the pond.
 for(let i=0;i<12;i++){let a=i*Math.PI/6,x=27+Math.cos(a)*4.7,z=13+Math.sin(a)*4.7;let reed=cyl(scene,x,.48,z,.035,.045,.9,M(0x548d59),6);reed.rotation.z=Math.cos(a)*.18;let pad=ball(scene,27+Math.cos(a)*2.5,.13,13+Math.sin(a)*2.5,.38,M(0x4c9b68));pad.scale.set(1,.12,.72);if(i%3===0)ball(scene,27+Math.cos(a)*2.5,.23,13+Math.sin(a)*2.5,.12,M(0xf4b6d0))}
 // A few distant rocky islets give the ocean a horizon and a sense of scale.
 for(let i=0;i<5;i++){let a=i*1.256,r=76+(i%2)*10,x=Math.cos(a)*r,z=Math.sin(a)*r;let island=group(scene,x,-.35,z);let base=ball(island,0,0,0,7,mat.sand);base.scale.set(1,.12,.72);let top=ball(island,0,.55,0,5.5,mat.grass);top.scale.set(1,.12,.72);for(let t=0;t<3;t++){let trunk=cyl(island,(t-1)*1.5,1.5,0,.22,.28,2.8,mat.wood);ball(island,(t-1)*1.5,3.1,0,1.5,mat.leaf)}}
}
function addFreeScenery(url,placements,height=2){modelLoader.load(url,gltf=>{const source=gltf.scene.clone(true);source.traverse(n=>{if(n.isMesh){n.castShadow=placements.length<=8;n.receiveShadow=true;if(n.material){n.material.envMapIntensity=1.05;n.material.needsUpdate=true}}});const b=new THREE.Box3().setFromObject(source),size=b.getSize(new THREE.Vector3());if(!size.y)return;source.scale.setScalar(height/size.y);const scaled=new THREE.Box3().setFromObject(source),center=scaled.getCenter(new THREE.Vector3());source.position.set(-center.x,-scaled.min.y,-center.z);placements.forEach(([x,z,scale=1,turn=0])=>{const obj=source.clone(true);obj.position.x+=x;obj.position.z+=z;obj.position.y+=terrainHeight(x,z);obj.scale.multiplyScalar(scale);obj.rotation.y=turn;scene.add(obj)})},undefined,e=>console.warn("3D-Umgebungsmodell nicht geladen:",url,e))}
function addAuthoredBuilding(url,x,z,height,placeholder,beacon=false){modelLoader.load(url,gltf=>{const model=gltf.scene.clone(true);model.traverse(n=>{if(n.isMesh){n.castShadow=true;n.receiveShadow=true;if(n.material){n.material.envMapIntensity=1.15;n.material.needsUpdate=true}}});const bounds=new THREE.Box3().setFromObject(model),size=bounds.getSize(new THREE.Vector3());if(!size.y)return;model.scale.setScalar(height/size.y);const scaled=new THREE.Box3().setFromObject(model),center=scaled.getCenter(new THREE.Vector3()),ground=terrainHeight(x,z);model.position.set(x-center.x,ground-scaled.min.y,z-center.z);scene.add(model);if(placeholder)placeholder.visible=false;if(beacon&&adv.upgrades?.lighthouse){const lamp=new THREE.PointLight(0xffd98c,3.2,34);lamp.position.set(x,ground+height*.78,z);scene.add(lamp);const glow=new THREE.Mesh(new THREE.SphereGeometry(.3,12,8),new THREE.MeshBasicMaterial({color:0xffe6a6}));glow.position.copy(lamp.position);scene.add(glow)}},undefined,e=>console.warn("Architekturmodell nicht geladen:",url,e))}
function loadCloudModels(){const files=["Cloud001.glb","Cloud002.glb","Cloud003.glb"];files.forEach((file,index)=>modelLoader.load(GOBKIT+"environment/"+file,gltf=>{const source=gltf.scene,bounds=new THREE.Box3().setFromObject(source),size=bounds.getSize(new THREE.Vector3()),center=bounds.getCenter(new THREE.Vector3());if(!size.x)return;for(let i=0;i<5;i++){const g=source.clone(true),scale=7.5/Math.max(size.x,size.z),x=-46+i*24+index*4,z=-48+(i%3)*22+index*5,y=18+(i%2)*4;g.scale.setScalar(scale);g.position.set(x-center.x*scale,y-center.y*scale,z-center.z*scale);scene.add(g);clouds.push({g,speed:.24+(i%3)*.1})}},undefined,e=>console.warn("Wolkenmodell nicht geladen:",file,e)))}
