function makeBuildObject(id,x,z,rot=0,persist=true){let g=group(scene,x,0,z);if(id==="tree"){cyl(g,0,.8,0,.18,.23,1.6,mat.wood);ball(g,0,1.9,0,.95,mat.leaf)}else if(id==="lamp"){cyl(g,0,1,0,.07,.09,2,mat.dark);ball(g,0,2.1,0,.25,mat.gold);let l=new THREE.PointLight(0xffd78a,.7,6);l.position.y=2;g.add(l)}else if(id==="bench"){box(g,0,.58,0,1.5,.18,.48,mat.wood);for(let q of [-.55,.55])box(g,q,.3,0,.13,.6,.42,mat.dark)}else if(id==="flower"){for(let i=0;i<5;i++)flower(x+Math.cos(i*1.25)*.35,z+Math.sin(i*1.25)*.35,0xffb5d2)}else if(id==="fountain"){cyl(g,0,.2,0,1.2,1.2,.35,mat.stone,20);cyl(g,0,.75,0,.25,.3,1,mat.stone);ball(g,0,1.25,0,.32,mat.blue)}else if(id==="campfire"){for(let i=0;i<5;i++){let q=box(g,0,.18,0,.9,.15,.16,mat.wood);q.rotation.y=i*.65}cone(g,0,.65,0,.38,.9,M(0xf08b43),7);let l=new THREE.PointLight(0xff8b45,1.2,7);l.position.y=.8;g.add(l)}else if(id==="pond"){let p=new THREE.Mesh(new THREE.CircleGeometry(1.7,24),M(0x65b9c7,.35));p.rotation.x=-Math.PI/2;p.position.y=.06;g.add(p)}g.rotation.y=rot;decor.push(g);if(persist){data.placed.push({id,x,z,rot});save();window.dispatchEvent(new CustomEvent("studyspace:island-progress",{detail:{type:"build",id:"placed:"+data.placed.length,count:data.placed.length}}))}return g}
function makePlayer(){let g=group(scene,data.x||0,0,data.z||8),b=group(g);cyl(b,0,.9,0,.36,.43,.9,M(0x658fd9));ball(b,0,1.62,0,.35,M(0xf0c6a0));ball(b,0,1.91,-.04,.37,M(0x654b3d));ball(b,-.12,1.68,.31,.045,mat.dark);ball(b,.12,1.68,.31,.045,mat.dark);ball(b,0,1.48,.34,.055,M(0xd27d75));for(let x of [-.16,.16]){let leg=cyl(b,x,.25,0,.12,.14,.5,M(0x4d526a),10);let shoe=ball(b,x,.05,.1,.15,mat.dark);let arm=box(b,x*2.5,.98,0,.17,.64,.18,M(0x658fd9));arm.rotation.z=x*1.4}let pack=box(b,0,1.05,-.29,.48,.55,.22,M(0xa77b50));g.userData.body=b;g.userData.parts={};loadRiggedCharacter(GOBKIT+"human013/Prince.glb",g,1.95);return g}
function ui(){root=document.createElement("div");root.id="ss3d-game";root.innerHTML='<div class="ss3d-top"><div class="ss3d-brand"><span>✦</span><div><b>STERNENINSEL</b><small>Dein 3D-Inselabenteuer</small></div></div><div class="ss3d-stats"><span id="ss3d-coins">🪙 0</span><span id="ss3d-shells">🐚 0</span><span id="ss3d-xp">⭐ Level 1</span><span id="ss3d-clock">☀️ Tag 1 · 09:00</span></div><div class="ss3d-controls"><button id="ss3d-map">🗺 Karte</button><button id="ss3d-full">⛶</button><button id="ss3d-exit">✕</button></div></div><div class="ss3d-bottom"><div class="ss3d-quest"><small>DEIN ABENTEUER</small><b id="ss3d-quest-title">Die Sterneninsel entdecken</b><span id="ss3d-quest-text">Sprich mit Mira und erkunde die Insel.</span></div><div class="ss3d-hint" id="ss3d-hint">WASD bewegen · Maus drehen · E interagieren · B bauen</div></div><div class="ss3d-dialogue" id="ss3d-dialogue"><div><small id="ss3d-speaker"></small><p id="ss3d-line"></p><button id="ss3d-close-dialogue">Weiter</button></div></div><div class="ss3d-build" id="ss3d-build"><div class="ss3d-build-head"><div><small>INSELWERKSTATT</small><b>Baumodus</b></div><button id="ss3d-build-close">✕</button></div><p>Wähle ein Objekt. Klicke auf den Boden, um es zu platzieren. R dreht es.</p><div id="ss3d-build-items"></div><div class="ss3d-build-foot"><button id="ss3d-build-rotate">↻ Drehen</button><button id="ss3d-build-done">Fertig</button></div></div><div class="ss3d-map" id="ss3d-map-panel"><div><b>Deine Sterneninsel</b><button id="ss3d-map-close">✕</button></div><p>Dorfplatz · Blütengarten · Flüsterwald · Sternenbucht</p><small>Die weiteren Gebiete werden durch Storykapitel und Lernfortschritte entdeckt.</small></div><div class="ss3d-touch-ui"><div class="ss3d-stick" id="ss3d-stick"><div class="ss3d-stick-ring"></div><div class="ss3d-stick-knob" id="ss3d-stick-knob"></div></div><div class="ss3d-touch-actions"><button data-action="interact"><b> E </b><small>Interagieren</small></button><button id="ss3d-touch-build"><b>✦</b><small>Bauen</small></button></div></div>';document.body.appendChild(root);root.addEventListener("click",uiClick);$("ss3d-full").textContent="⛶ Vollbild";$("ss3d-full").title="Vollbild ein-/ausschalten";$("ss3d-full").onclick=()=>{if(document.fullscreenElement){document.exitFullscreen?.()}else{root.requestFullscreen?.().catch(()=>toast("Vollbild wird von diesem Browser nicht unterstützt."))}};document.addEventListener("fullscreenchange",()=>{let f=$("ss3d-full");if(f)f.textContent=document.fullscreenElement?"⤢ Fenster":"⛶ Vollbild"});$("ss3d-exit").onclick=close;$("ss3d-close-dialogue").onclick=hideDialogue;$("ss3d-build-close").onclick=()=>toggleBuild(false);$("ss3d-build-done").onclick=()=>toggleBuild(false);$("ss3d-build-rotate").onclick=rotateBuild;$("ss3d-map").onclick=()=>$("ss3d-map-panel").classList.toggle("visible");$("ss3d-map-close").onclick=()=>$("ss3d-map-panel").classList.remove("visible");root.querySelectorAll("[data-move]").forEach(b=>{b.addEventListener("pointerdown",e=>{e.preventDefault();keys[b.dataset.move]=true});["pointerup","pointerleave","pointercancel"].forEach(n=>b.addEventListener(n,()=>keys[b.dataset.move]=false))});renderBuild();$("ss3d-touch-build").onclick=()=>toggleBuild(!buildMode);const stick=$("ss3d-stick");stick.addEventListener("pointerdown",stickDown);stick.addEventListener("pointermove",stickMove);stick.addEventListener("pointerup",stickUp);stick.addEventListener("pointercancel",stickUp);stick.addEventListener("lostpointercapture",stickUp)}
function uiClick(e){let a=e.target.closest("[data-action]");if(a)interact();let b=e.target.closest("[data-build]");if(b){selectedBuild=b.dataset.build;root.querySelectorAll("[data-build]").forEach(x=>x.classList.toggle("selected",x===b));toast("Platziere "+catalog.find(x=>x[0]===selectedBuild)[2]+".");}}
